// Appended to an extracted production Activity harness; only Android/network/storage boundaries are faked.
 static final String ID="01234567-89ab-4def-8123-456789abcdef", OTHER="fedcba98-7654-4321-8123-456789abcdef";
 static final String TOKEN="a".repeat(64);
 static int passed;
 interface Checked {void run() throws Exception;}
 static void test(String name,Checked run)throws Exception{run.run();passed++;System.out.println("PASS "+name);}
 static void check(boolean v){if(!v)throw new AssertionError();}
 static void rejects(Checked run)throws Exception{try{run.run();}catch(IllegalArgumentException expected){return;}throw new AssertionError("accepted invalid response");}
 static JSONObject summary(String id){return new JSONObject().put("report_id",id).put("title","连接恢复问题").put("status","new").put("created_at",1793000000L).put("updated_at",1793000001L).put("expires_at",1795592000L).put("duplicate_of",JSONObject.NULL);}
 static JSONObject list(String cursor){return new JSONObject().put("protocol_version",4).put("reports",new JSONArray().put(summary(ID))).put("next_cursor",cursor);}
 static JSONObject report(String id){return new JSONObject().put("protocol_version",4).put("report",summary(id).put("description","打开后未连接").put("supplements",new JSONArray()).put("maintenance_reply","正在检查"));}
 static JSONObject deleted(String id){return new JSONObject().put("protocol_version",4).put("ok",true).put("deleted",true).put("report_id",id);}
 static FeedbackApi.Pending last(){return FeedbackApi.calls.get(FeedbackApi.calls.size()-1);}
 static FeedbackHarness start(){EnrollmentStore.fail=false;EnrollmentStore.value=new EnrollmentStore.Config("https://relay.invalid/d/"+"1".repeat(32),TOKEN);FeedbackApi.calls.clear();FeedbackHarness h=new FeedbackHarness();h.content=new LinearLayout();h.scroll=new ScrollView();h.onResume();return h;}
 static FeedbackHarness withDetail(){FeedbackHarness h=start();last().reply(list(null),200,null);h.loadDetail(ID);last().reply(report(ID),200,null);return h;}
 public static void main(String[] args)throws Exception{
  test("owner list works independently of controller grant",()->{FeedbackHarness h=start();check("GET".equals(last().method)&&last().id==null);last().reply(list(null),200,null);check(h.page.reports.size()==1&&!h.busy);});
  test("pause cancels request clears content and rejects delayed response",()->{FeedbackHarness h=start();FeedbackApi.Pending p=last();h.onPause();int renders=h.renders;p.reply(list(null),200,null);check(p.cancelled&&h.page==null&&h.renders==renders&&h.content.cleared==1);});
  test("resume fences old response before accepting new request",()->{FeedbackHarness h=start();FeedbackApi.Pending p=last();h.onPause();h.onResume();FeedbackApi.Pending fresh=last();p.reply(list(null),200,null);check(h.page==null&&h.busy);fresh.reply(list(null),200,null);check(h.page!=null&&!h.busy);});
  test("destroy fences pending response",()->{FeedbackHarness h=start();FeedbackApi.Pending p=last();h.onDestroy();p.reply(list(null),200,null);check(h.page==null&&p.cancelled);});
  test("new request cannot be released by older success",()->{FeedbackHarness h=start();FeedbackApi.Pending p=last();h.loadDetail(ID);p.reply(list(null),200,null);check(h.busy&&h.page==null);last().reply(report(ID),200,null);check(h.detail!=null&&!h.busy);});
  test("new request cannot be released by older failure",()->{FeedbackHarness h=start();FeedbackApi.Pending p=last();h.loadDetail(ID);p.reply(null,503,"unavailable");check(h.busy&&h.message.isEmpty());});
  test("token replacement rejects old report even at same service",()->{FeedbackHarness h=start();FeedbackApi.Pending p=last();EnrollmentStore.value=new EnrollmentStore.Config(EnrollmentStore.value.url,"b".repeat(64));p.reply(list(null),200,null);check(h.identityChanged&&h.page==null&&!h.busy);});
  test("service replacement rejects detail and removes old page",()->{FeedbackHarness h=withDetail();h.loadDetail(ID);FeedbackApi.Pending p=last();EnrollmentStore.value=new EnrollmentStore.Config("https://other.invalid/d/"+"1".repeat(32),TOKEN);p.reply(report(ID),200,null);check(h.identityChanged&&h.detail==null&&h.page==null);});
  test("forgotten enrollment rejects late reply",()->{FeedbackHarness h=start();FeedbackApi.Pending p=last();EnrollmentStore.value=null;p.reply(list(null),200,null);check(h.identityChanged&&h.page==null);});
  test("unenrolled device cannot send owner request",()->{FeedbackHarness h=start();h.onPause();EnrollmentStore.value.registered=false;int calls=FeedbackApi.calls.size();h.onResume();check(h.identityChanged&&calls==FeedbackApi.calls.size());});
  test("storage read failure does not display old report",()->{FeedbackHarness h=start();FeedbackApi.Pending p=last();EnrollmentStore.fail=true;p.reply(list(null),200,null);check(h.identityChanged&&h.page==null);EnrollmentStore.fail=false;});
  test("resume after identity switch does not automatically use new device",()->{FeedbackHarness h=withDetail();h.onPause();int calls=FeedbackApi.calls.size();EnrollmentStore.value=new EnrollmentStore.Config("https://other.invalid/d/"+"2".repeat(32),TOKEN);h.onResume();check(h.identityChanged&&calls==FeedbackApi.calls.size());});
  test("single explicit delete cannot be double sent",()->{FeedbackHarness h=withDetail();h.delete();int calls=FeedbackApi.calls.size();h.delete();check(calls==FeedbackApi.calls.size()&&"DELETE".equals(last().method)&&h.deleteUncertain&&h.busy);});
  test("unknown deletion is not automatically repeated",()->{FeedbackHarness h=withDetail();h.delete();last().reply(null,0,"network_unconfirmed");int calls=FeedbackApi.calls.size();h.delete();check(h.deleteUncertain&&!h.busy&&h.message.contains("暂未确认")&&calls==FeedbackApi.calls.size());});
  test("refresh verifies successful deletion after lost response",()->{FeedbackHarness h=withDetail();h.delete();last().reply(null,0,"network_unconfirmed");h.loadDetail(ID);check("GET".equals(last().method));last().reply(null,410,"report_deleted");check(h.detail==null&&h.message.equals("这份报告已删除。"));});
  test("refresh verifies report remains before permitting fresh explicit delete",()->{FeedbackHarness h=withDetail();h.delete();last().reply(null,0,"network_unconfirmed");h.loadDetail(ID);last().reply(report(ID),200,null);check(!h.deleteUncertain&&h.detail!=null);h.delete();check("DELETE".equals(last().method));});
  test("pause during deletion never replays mutation on resume",()->{FeedbackHarness h=withDetail();h.delete();FeedbackApi.Pending p=last();h.onPause();h.onResume();check("GET".equals(last().method));int renders=h.renders;p.reply(deleted(ID),200,null);check(h.renders==renders&&h.busy&&h.deleteUncertain);});
  test("delete success requires matching report id",()->{FeedbackHarness h=withDetail();h.delete();last().reply(deleted(OTHER),200,null);check(h.selectedId.equals(ID)&&h.deleteUncertain&&h.message.contains("暂未确认"));});
  test("confirmed delete refreshes owner list exactly once",()->{FeedbackHarness h=withDetail();h.delete();int calls=FeedbackApi.calls.size();last().reply(deleted(ID),200,null);check(FeedbackApi.calls.size()==calls+1&&"GET".equals(last().method)&&last().id==null&&h.selectedId==null);});
  test("config rechecked before deleting instead of only on callback",()->{FeedbackHarness h=withDetail();EnrollmentStore.value=null;int calls=FeedbackApi.calls.size();h.delete();check(h.identityChanged&&calls==FeedbackApi.calls.size());});
  test("cursor round trip and previous-page history stay opaque",()->{FeedbackHarness h=start();last().reply(list("opaque_cursor-2"),200,null);List<String> path=new ArrayList<>();path.add(null);h.loadPage(h.page.nextCursor,path);check(last().cursor.equals("opaque_cursor-2"));last().reply(list("opaque_cursor-3"),200,null);check(h.history.size()==1&&h.cursor.equals("opaque_cursor-2")&&h.page.nextCursor.equals("opaque_cursor-3"));});
  test("failed next-page read preserves previous navigation",()->{FeedbackHarness h=start();last().reply(list("next"),200,null);h.loadPage("next",Arrays.asList((String)null));last().reply(null,503,"unavailable");check(h.cursor==null&&h.history.isEmpty()&&h.page.nextCursor.equals("next"));});
  test("cursor cycles rejected without losing loaded page",()->{FeedbackHarness h=start();last().reply(list("next"),200,null);h.loadPage("next",Arrays.asList((String)null));last().reply(list("next"),200,null);check(h.cursor==null&&h.message.contains("暂时无法"));});
  test("successful resume clears earlier list failure",()->{FeedbackHarness h=start();last().reply(null,503,"unavailable");check(h.message.contains("暂时无法"));h.onPause();h.onResume();last().reply(list(null),200,null);check(h.page!=null&&h.message.isEmpty());});
  test("detail body is bound to selected report id",()->rejects(()->new FeedbackReport.Detail(report(OTHER),ID)));
  test("non-BMP description respects code points not UTF16 units",()->{JSONObject body=report(ID);body.getJSONObject("report").put("description","😀".repeat(4001));check(new FeedbackReport.Detail(body,ID).sections.get(0).text.codePointCount(0,8002)==4001);});
  test("non-BMP title respects backend 160 character bound",()->{JSONObject body=report(ID);body.getJSONObject("report").put("title","😀".repeat(160));check(new FeedbackReport.Detail(body,ID).summary.title.length()==320);});
  test("description beyond contract rejected rather than silently truncated",()->{JSONObject body=report(ID);body.getJSONObject("report").put("description","😀".repeat(8001));rejects(()->new FeedbackReport.Detail(body,ID));});
  test("malformed numeric dates rejected",()->{JSONObject body=report(ID);body.getJSONObject("report").put("expires_at","1795592000");rejects(()->new FeedbackReport.Detail(body,ID));body.getJSONObject("report").put("expires_at",Double.NaN);rejects(()->new FeedbackReport.Detail(body,ID));});
  test("date overflow rejected",()->{JSONObject body=report(ID);body.getJSONObject("report").put("expires_at",Long.MAX_VALUE);rejects(()->new FeedbackReport.Detail(body,ID));});
  test("raw server objects never coerced into displayed text",()->{JSONObject body=report(ID);body.getJSONObject("report").put("maintenance_reply",new JSONObject().put("token",TOKEN));rejects(()->new FeedbackReport.Detail(body,ID));});
  test("unknown fields do not enter displayed report sections",()->{JSONObject body=report(ID);body.getJSONObject("report").put("device_token",TOKEN).put("untrusted_html","<script>attack</script>");FeedbackReport.Detail d=new FeedbackReport.Detail(body,ID);check(d.sections.size()==1&&d.sections.get(0).text.equals("打开后未连接"));});
  test("report text remains literal including HTML URLs and code",()->{String text="<script>alert(1)</script> https://example.invalid/\nAuthorization: Bearer SAMPLE\napi_key=placeholder";check(FeedbackText.display(text,TOKEN).equals(text));});
  test("only known device token exact matches hidden",()->{String value="first "+TOKEN+" second "+TOKEN+" hash "+"b".repeat(64);String result=FeedbackText.display(value,TOKEN);check(!result.contains(TOKEN)&&result.contains("b".repeat(64))&&result.split("连接凭据已隐藏",-1).length==3);});
  test("unknown status is local fallback not untrusted label",()->check(FeedbackText.status("<script>look here</script>").equals("状态待更新")));
  test("path traversal and hostile cursor rejected",()->{check(!FeedbackReport.validId("../../delete"));check(!FeedbackReport.validCursor("next&token=bad"));check(!FeedbackReport.validCursor("x".repeat(257)));});
  test("missing pagination token not silently treated as last page",()->{JSONObject body=list(null);body.remove("next_cursor");rejects(()->new FeedbackReport.Page(body));});
  test("malformed delete success is unconfirmed",()->{JSONObject body=deleted(ID).put("deleted","true");check(!FeedbackReport.deleted(body,ID));});
  test("supplement limit is enforced without truncation",()->{JSONObject body=report(ID);JSONArray additions=new JSONArray();for(int i=0;i<6;i++)additions.put(new JSONObject().put("text","补充").put("created_at",1793000000L));body.getJSONObject("report").put("supplements",additions);rejects(()->new FeedbackReport.Detail(body,ID));});
  System.out.println("TOTAL "+passed);
 }
